LANGUAGE_NAMES = {'en': 'English', 'ar': 'Arabic', 'fr': 'French', 'ur': 'Urdu', 'hi': 'Hindi', 'bn': 'Bengali'}
LANG_NATIVE = {'en': 'English', 'ar': 'العربية', 'fr': 'Français', 'ur': 'اردو', 'hi': 'हिन्दी', 'bn': 'বাংলা'}
RTL_LANGS = {'ar', 'ur'}


def t(key, locale):
    """Return the caption for `key` in `locale`, falling back to English
    (and finally the raw key) when no translation is available."""
    entry = CAPTIONS.get(key)
    if not entry:
        return key
    return entry.get(locale) or entry.get('en') or key


def t_other(key, current_locale, configured_lang):
    """The mirror of t(): return the caption in whichever language is NOT
    currently active. Used for the Owner Form's secondary bilingual-pair
    labels/placeholders, which always show the "other" language name next
    to the primary (active-language) one -- e.g. bi-lbl-ar / the *_s
    secondary input placeholder."""
    other_locale = 'en' if current_locale != 'en' else configured_lang
    return t(key, other_locale)


def dual(key, current_locale, configured_lang):
    """Render a "PrimaryLang / SecondaryLang" bilingual label -- the style
    used throughout the Owner Form's field labels (e.g. "Name / الاسم").

    Always pairs English with the Owner's configured Second Language,
    regardless of what the current viewer happens to have selected on the
    dashboard -- these labels describe the field itself, in the app's two
    official languages, not the viewer's personal pick. Order flips so the
    currently-active language reads first.
    """
    entry = CAPTIONS.get(key) or {}
    en_text = entry.get('en', key)
    other_text = entry.get(configured_lang) or en_text
    if current_locale == 'en':
        return f'{en_text} / {other_text}'
    return f'{other_text} / {en_text}'
